    if ' ' in txt or '\t' in txt or '\n' in txt or '\r' in txt:
        return txt.split()

    # Check if there is any comma
    if ',' in txt:
        return txt.split(',')

    # Count lower-case letters with odd order in the alphabet (a=0, b=1, ..., z=25)
    # Odd order means the index is odd: b(1), d(3), f(5), ..., y(25)
    count = 0
    for char in txt:
        if 'a' <= char <= 'z':
            index = ord(char) - ord('a')
            if index % 2 == 1:
                count += 1
    return count
